mapper.select:
/** mainbanner-mapper.getMainBannerList (메인 배너 목록) */ SELECT MB.BANNER_ID, MB.TITLE, MB.LINK_URL, MB.CONTENTS, MB.DISPLAY_ORDER, MB.CREATED_DATE, MB.PC_FILE_NAME, MB.M_FILE_NAME, MB.PC_ORG_FILE_NAME, MB.M_ORG_FILE_NAME, MB.DISPLAY_FLAG FROM OP_MAIN_BANNER MB WHERE 1=1
AND MB.DISPLAY_FLAG = #{displayFlag}
ORDER BY MB.DISPLAY_ORDER

mapper.update:
/** mainbanner-mapper.updateDisplayOrder (메인 배너 순서 변경) */
UPDATE
		OP_MAIN_BANNER
SET
		DISPLAY_ORDER = #{displayOrder}
WHERE
		BANNER_ID = #{bannerId}

/** mainbanner-mapper.updateMainBannerFileDel (메인 배너 논리적 파일 삭제) */ UPDATE OP_MAIN_BANNER SET BANNER_ID = #{bannerId}
, PC_FILE_NAME = NULL , PC_ORG_FILE_NAME = NULL
, M_FILE_NAME = NULL , M_ORG_FILE_NAME = NULL
WHERE BANNER_ID = #{bannerId}
